from heapq import heappush, heappop
import math

class Graph:

    def __init__(self, graph):
        self.__graph = graph

    def dijkstra_path(self, source, target):
        dist = {node: math.inf for node in self.__graph}
        dist[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current_vertex = heappop(queue)
            if current_distance > dist[current_vertex]:
                continue
            for neighbor, weight in self.__graph.get(current_vertex, []):
                dist_sum = current_distance + weight
                if dist_sum < dist[neighbor]:
                    dist[neighbor] = dist_sum
                    heappush(queue, (dist_sum, neighbor))
        if dist[target] == math.inf:
            return (float('inf'), None)
        path = [target]
        current_vertex = target
        while current_vertex != source:
            for neighbor, _ in self.__graph.get(current_vertex, []):
                if dist[neighbor] == dist[current_vertex] - 1:
                    current_vertex = neighbor
                    path.append(current_vertex)
                    break
        path.reverse()
        return (dist[target], path)
