from heapq import heappop, heappush

def shortest_path(V as dict, source, target):
    # Initialization
    if source not in V or target not in V:
        return float('inf'), None
    distances = {node: float('inf') for node in V}
    distances[source] = 0    
    path_queue = [(0, source)]
    parent_map = {}

    # Dijkstra's algorithm
    while path_queue:
        current_distance, current_node = heappop(path_queue)

        if current_node == target or current_distance == float('inf'):
            break

        for neighboring_node, weight in V[current_node]:
            distance = current_distance + weight

            if distance < distances[neighboring_node]:
                distances[neighboring_node] = distance
                parent_map[neighboring_node] = (current_node, weight)
                heappush(path_queue, (distance, neighboring_node))

    if distances[target] == float('inf'):
        return float('inf'), None
    else:
        path = []
        node = target
        while node:
            path.insert(0, node)
            _, prev_node = parent_map[node]
            node = prev_node
        return (distances[target], path)

