from collections import deque

def shortest_path(graph, source, target):
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    queue = deque([source])
    previous = {node: None for node in graph}
    processed = set()

    def relax(u, v, weight):
        nonlocal previous, distances
        if distances[v] > distances[u] + weight:
            distances[v] = distances[u] + weight
            previous[v] = u
            if v not in processed:
                queue.append(v)
    while queue:
        u = queue.popleft()
        processed.add(u)
        for i, (v, weight) in enumerate(graph[u]):
            relax(u, v, weight)
            if v == target:
                path = []
                while v:
                    path.append(v)
                    v = previous[v]
                return (distances[target], list(reversed(path)))
        for node in graph:
            if node not in processed and node not in queue:
                queue.append(node)
    return (float('inf'), None)
